insert into public.spots (id, city_id, name, type, genres, window_type, reason, tagline, why, look, getting, image_url, lat, lon, published) values (
  $vtg$john-seigenthaler-pedestrian-bridge$vtg$, $vtg$nashville$vtg$, $vtg$John Seigenthaler Pedestrian Bridge$vtg$, $vtg$Cityscape$vtg$, array[$vtg$Street$vtg$, $vtg$Architecture$vtg$, $vtg$Landscape$vtg$]::text[], $vtg$blue$vtg$, $vtg$Skyline reflections over the Cumberland at dusk$vtg$, $vtg$A truss bridge with the whole downtown skyline behind it$vtg$, $vtg$This old truss bridge gives you a clean, elevated line right toward the downtown towers, with the Cumberland River curving below. The steel framework overhead makes a ready-made leading line, and once the city lights come on the whole scene reflects off the water. It's one of the few spots in Nashville where you get skyline, river, and architecture in a single frame.$vtg$, array[$vtg$The truss beams overhead framing the downtown towers as you shoot east$vtg$, $vtg$Long exposure of the river catching skyline lights at blue hour$vtg$, $vtg$A lone walker or cyclist mid-span for scale against the steel$vtg$]::text[], $vtg$On the east edge of downtown, spanning the Cumberland near Nissan Stadium; walk on from either bank, park downtown or across the river.$vtg$, null, 36.162298, -86.772372, true)
  on conflict (id) do update set city_id=excluded.city_id, name=excluded.name, type=excluded.type, genres=excluded.genres, window_type=excluded.window_type, reason=excluded.reason, tagline=excluded.tagline, why=excluded.why, look=excluded.look, getting=excluded.getting, lat=excluded.lat, lon=excluded.lon, published=excluded.published;
insert into public.spots (id, city_id, name, type, genres, window_type, reason, tagline, why, look, getting, image_url, lat, lon, published) values (
  $vtg$capitol-boulevard$vtg$, $vtg$nashville$vtg$, $vtg$Capitol Boulevard$vtg$, $vtg$Architecture$vtg$, array[$vtg$Architecture$vtg$, $vtg$Street$vtg$]::text[], $vtg$blue$vtg$, $vtg$Brick facades and warm windows at dusk$vtg$, $vtg$A short, storied block where old Nashville still leans in close.$vtg$, $vtg$Capitol Boulevard is a compact, walkable stretch that trades the glass towers downtown for older brick storefronts, tall arched windows, and the kind of human-scale detail you can actually frame. As blue hour settles, the warm interior light of restaurants and bars plays against the cooling sky, and the state capitol rising nearby gives you a payoff at the top of the street. It's the rare downtown block that feels intimate rather than overwhelming.$vtg$, array[$vtg$The capitol dome framed at the end of the boulevard as the sky goes deep blue$vtg$, $vtg$Warm window light spilling onto brick facades and wet pavement after rain$vtg$, $vtg$A single figure crossing the crosswalk against glowing storefronts at dusk$vtg$]::text[], $vtg$Right on the north edge of downtown near the capitol; walkable from Broadway with metered street parking and nearby garages.$vtg$, null, 36.163846, -86.782968, true)
  on conflict (id) do update set city_id=excluded.city_id, name=excluded.name, type=excluded.type, genres=excluded.genres, window_type=excluded.window_type, reason=excluded.reason, tagline=excluded.tagline, why=excluded.why, look=excluded.look, getting=excluded.getting, lat=excluded.lat, lon=excluded.lon, published=excluded.published;
insert into public.spots (id, city_id, name, type, genres, window_type, reason, tagline, why, look, getting, image_url, lat, lon, published) values (
  $vtg$deaderick-street$vtg$, $vtg$nashville$vtg$, $vtg$Deaderick Street$vtg$, $vtg$Architecture$vtg$, array[$vtg$Architecture$vtg$, $vtg$Street$vtg$]::text[], $vtg$blue$vtg$, $vtg$Glass towers and clean lines at dusk$vtg$, $vtg$Downtown's tidy corridor of glass, stone, and symmetry$vtg$, $vtg$Deaderick is a short, walkable stretch that packs a lot of downtown geometry into a few blocks — the reflective face of state office buildings, clean pedestrian paving, and sightlines that funnel toward the Capitol up the hill. It's quiet enough that you can actually set up a frame without dodging crowds, and the mix of modern glass and older stone gives you contrast in a single shot. Blue hour is when the office lights kick on and the glass turns to layered reflections.$vtg$, array[$vtg$The uphill sightline toward the Capitol, compressed with a longer lens at dusk$vtg$, $vtg$Reflections of one building's facade in the glass of another after office lights come on$vtg$, $vtg$A lone pedestrian crossing the empty street for scale against the towers$vtg$]::text[], $vtg$Right in downtown Nashville near the Capitol; walkable from the core, with paid garages and metered street parking nearby.$vtg$, null, 36.164735, -86.782883, true)
  on conflict (id) do update set city_id=excluded.city_id, name=excluded.name, type=excluded.type, genres=excluded.genres, window_type=excluded.window_type, reason=excluded.reason, tagline=excluded.tagline, why=excluded.why, look=excluded.look, getting=excluded.getting, lat=excluded.lat, lon=excluded.lon, published=excluded.published;
insert into public.spots (id, city_id, name, type, genres, window_type, reason, tagline, why, look, getting, image_url, lat, lon, published) values (
  $vtg$woodland-street-bridge$vtg$, $vtg$nashville$vtg$, $vtg$Woodland Street Bridge$vtg$, $vtg$Architecture$vtg$, array[$vtg$Architecture$vtg$, $vtg$Landscape$vtg$, $vtg$Street$vtg$]::text[], $vtg$blue$vtg$, $vtg$Skyline reflections over the Cumberland at dusk$vtg$, $vtg$A pedestrian-friendly perch on the downtown skyline$vtg$, $vtg$The Woodland Street Bridge hands you one of Nashville's cleanest skyline views, with the Cumberland River curving beneath and the downtown towers stacking up on the far bank. There's a wide walkway so you can set up without dodging traffic, and the light at blue hour turns the whole scene into glass and neon. It's the kind of spot where the city photographs itself if you just wait for the lights to come up.$vtg$, array[$vtg$The full downtown skyline glowing across the water right as blue hour peaks$vtg$, $vtg$Reflections of the AT&T 'Batman' building rippling on the Cumberland below$vtg$, $vtg$The bridge's own steel lines leading your eye toward the towers for a strong foreground$vtg$]::text[], $vtg$Short walk east from downtown or the Nissan Stadium side; easiest on foot from the riverfront area.$vtg$, null, 36.167678, -86.775585, true)
  on conflict (id) do update set city_id=excluded.city_id, name=excluded.name, type=excluded.type, genres=excluded.genres, window_type=excluded.window_type, reason=excluded.reason, tagline=excluded.tagline, why=excluded.why, look=excluded.look, getting=excluded.getting, lat=excluded.lat, lon=excluded.lon, published=excluded.published;
insert into public.spots (id, city_id, name, type, genres, window_type, reason, tagline, why, look, getting, image_url, lat, lon, published) values (
  $vtg$fort-nashborough$vtg$, $vtg$nashville$vtg$, $vtg$Fort Nashborough$vtg$, $vtg$Architecture$vtg$, array[$vtg$Architecture$vtg$, $vtg$Street$vtg$]::text[], $vtg$golden$vtg$, $vtg$Log fort walls against the river at dusk$vtg$, $vtg$A frontier stockade tucked below downtown's skyline$vtg$, $vtg$This reconstructed log fort sits right above the Cumberland River, and the rough-hewn timber walls make a rich contrast against Nashville's glass towers just uphill. It's small and often quiet, which means you can work the textures and lines without a crowd. Golden hour throws warm light across the logs and turns the whole stockade honey-colored.$vtg$, array[$vtg$Late sun raking across the chinked log walls, deep shadows in every gap$vtg$, $vtg$The blockhouse corner framed with downtown high-rises rising behind it$vtg$, $vtg$Down at the riverside walk, the fort's silhouette against the Cumberland at last light$vtg$]::text[], $vtg$On First Avenue North along the downtown riverfront; walkable from Broadway, with public lots and garages nearby.$vtg$, null, 36.164192, -86.775364, true)
  on conflict (id) do update set city_id=excluded.city_id, name=excluded.name, type=excluded.type, genres=excluded.genres, window_type=excluded.window_type, reason=excluded.reason, tagline=excluded.tagline, why=excluded.why, look=excluded.look, getting=excluded.getting, lat=excluded.lat, lon=excluded.lon, published=excluded.published;
insert into public.spots (id, city_id, name, type, genres, window_type, reason, tagline, why, look, getting, image_url, lat, lon, published) values (
  $vtg$symphony-place$vtg$, $vtg$nashville$vtg$, $vtg$Symphony Place$vtg$, $vtg$Architecture$vtg$, array[$vtg$Architecture$vtg$, $vtg$Street$vtg$]::text[], $vtg$blue$vtg$, $vtg$Curved glass and steel at dusk$vtg$, $vtg$Where the Schermerhorn's neighbor catches the last light$vtg$, $vtg$Symphony Place is a study in modern geometry sitting right next to the limestone classicism of the Schermerhorn Symphony Center, so you get contrast in one frame. The curved glass facade throws reflections of downtown and the changing sky, and the whole block gets quiet and clean once the workday crowd thins out. It's the kind of spot where the building does half the work for you.$vtg$, array[$vtg$The glass curtain wall reflecting the sky as blue hour deepens$vtg$, $vtg$The clash of the Schermerhorn's columns against the modern tower behind it$vtg$, $vtg$A lone figure crossing the plaza, lit by lobby glow after dark$vtg$]::text[], $vtg$In the SoBro/downtown core near the Schermerhorn, a short walk from Broadway; street parking or nearby garages.$vtg$, null, 36.160229, -86.775871, true)
  on conflict (id) do update set city_id=excluded.city_id, name=excluded.name, type=excluded.type, genres=excluded.genres, window_type=excluded.window_type, reason=excluded.reason, tagline=excluded.tagline, why=excluded.why, look=excluded.look, getting=excluded.getting, lat=excluded.lat, lon=excluded.lon, published=excluded.published;
insert into public.spots (id, city_id, name, type, genres, window_type, reason, tagline, why, look, getting, image_url, lat, lon, published) values (
  $vtg$whatliftsyou$vtg$, $vtg$nashville$vtg$, $vtg$WhatLiftsYou$vtg$, $vtg$Street art$vtg$, array[$vtg$Street$vtg$, $vtg$Portraits$vtg$]::text[], $vtg$flat$vtg$, $vtg$Iconic wings mural for portraits$vtg$, $vtg$Spread your wings on The Gulch's most-photographed wall$vtg$, $vtg$WhatLiftsYou is Kelsey Montague's angel-wing mural in The Gulch, and it's become Nashville's go-to spot for a stand-in-the-middle portrait. The white feathers pop against the brick, and the whole thing is built to put a person right at the center of the frame. Overcast light keeps the wings evenly lit and kills the harsh shadows that split the wall on bright afternoons.$vtg$, array[$vtg$Someone standing centered with arms out, wings framing them symmetrically$vtg$, $vtg$A tight detail crop on the feather tips against the red brick$vtg$, $vtg$The candid line of people waiting their turn, phones up, on the sidewalk$vtg$]::text[], $vtg$In The Gulch on 11th Ave S; walkable from downtown, with paid lots and garages nearby.$vtg$, null, 36.15391, -86.784019, true)
  on conflict (id) do update set city_id=excluded.city_id, name=excluded.name, type=excluded.type, genres=excluded.genres, window_type=excluded.window_type, reason=excluded.reason, tagline=excluded.tagline, why=excluded.why, look=excluded.look, getting=excluded.getting, lat=excluded.lat, lon=excluded.lon, published=excluded.published;
insert into public.spots (id, city_id, name, type, genres, window_type, reason, tagline, why, look, getting, image_url, lat, lon, published) values (
  $vtg$mixtape-memories-mural-wedgewood-houston$vtg$, $vtg$nashville$vtg$, $vtg$Mixtape: Memories mural (Wedgewood-Houston)$vtg$, $vtg$Street art$vtg$, array[$vtg$Street$vtg$, $vtg$Portraits$vtg$]::text[], $vtg$flat$vtg$, $vtg$Bold mural colors pop on overcast days$vtg$, $vtg$A wall built for color and portraits$vtg$, $vtg$The Mixtape mural in Wedgewood-Houston is a wash of saturated color and hand-lettered nostalgia that holds up as both a backdrop and a subject. WeHo's warehouse blocks give you room to work without crowds, and the flat, even light of an overcast day keeps those colors true instead of blown out. It's the kind of wall that turns a quick portrait shoot into something with real personality.$vtg$, array[$vtg$A subject standing dead-center, colors framing them on both sides$vtg$, $vtg$Tight crops on the lettering and cassette details for texture$vtg$, $vtg$Someone walking past mid-stride to add movement against the static wall$vtg$]::text[], $vtg$In the Wedgewood-Houston arts district south of downtown; easy street parking on the surrounding warehouse blocks.$vtg$, null, 36.131892, -86.768722, true)
  on conflict (id) do update set city_id=excluded.city_id, name=excluded.name, type=excluded.type, genres=excluded.genres, window_type=excluded.window_type, reason=excluded.reason, tagline=excluded.tagline, why=excluded.why, look=excluded.look, getting=excluded.getting, lat=excluded.lat, lon=excluded.lon, published=excluded.published;
insert into public.spots (id, city_id, name, type, genres, window_type, reason, tagline, why, look, getting, image_url, lat, lon, published) values (
  $vtg$printers-alley$vtg$, $vtg$nashville$vtg$, $vtg$Printers Alley$vtg$, $vtg$Architecture$vtg$, array[$vtg$Architecture$vtg$, $vtg$Street$vtg$]::text[], $vtg$blue$vtg$, $vtg$Vintage neon signs glowing after dark$vtg$, $vtg$A narrow lane of neon and old brick, best when the signs flicker on$vtg$, $vtg$Printers Alley is a tight cobblestone corridor packed with layered neon signs, weathered brick, and speakeasy doorways that light up as the sky drops to blue. It's one of the few spots downtown where the architecture and the light do the work for you — you just have to time it right. The alley's narrowness forces compression, so every frame stacks signs, fire escapes, and reflections into one dense scene.$vtg$, array[$vtg$The stacked neon signs converging down the alley just as blue hour hits and the cobblestones go wet-shiny$vtg$, $vtg$A doorway silhouette — someone stepping into a club under a glowing marquee$vtg$, $vtg$Tight detail on peeling brick, old ironwork, and a single buzzing sign against dark$vtg$]::text[], $vtg$Right in downtown Nashville between 3rd and 4th Avenues; walkable from Broadway, use a nearby downtown garage.$vtg$, null, 36.164512, -86.778678, true)
  on conflict (id) do update set city_id=excluded.city_id, name=excluded.name, type=excluded.type, genres=excluded.genres, window_type=excluded.window_type, reason=excluded.reason, tagline=excluded.tagline, why=excluded.why, look=excluded.look, getting=excluded.getting, lat=excluded.lat, lon=excluded.lon, published=excluded.published;
insert into public.spots (id, city_id, name, type, genres, window_type, reason, tagline, why, look, getting, image_url, lat, lon, published) values (
  $vtg$arcade-street$vtg$, $vtg$nashville$vtg$, $vtg$Arcade Street$vtg$, $vtg$Architecture$vtg$, array[$vtg$Architecture$vtg$, $vtg$Street$vtg$]::text[], $vtg$flat$vtg$, $vtg$Skylit Victorian arcade, layered symmetry$vtg$, $vtg$A glass-roofed corridor of light and old brick$vtg$, $vtg$The Arcade is one of Nashville's oldest indoor shopping passages, a two-story Victorian gallery capped by a peaked skylight that turns midday into soft, even light. The repeating storefronts, iron railings, and long central corridor hand you symmetry and leading lines almost for free. It's compact, weathered, and full of texture — a rare quiet interior in the middle of downtown.$vtg$, array[$vtg$Center yourself under the skylight and shoot straight down the corridor for a symmetrical vanishing point$vtg$, $vtg$Climb to the second-floor balcony and frame the geometry of the railings against the shop signs below$vtg$, $vtg$Catch a lone figure walking through the passage, backlit by the glass roof, for a moody street beat$vtg$]::text[], $vtg$Downtown between 4th and 5th Ave N; walkable from Broadway with nearby public parking garages.$vtg$, null, 36.164231, -86.780096, true)
  on conflict (id) do update set city_id=excluded.city_id, name=excluded.name, type=excluded.type, genres=excluded.genres, window_type=excluded.window_type, reason=excluded.reason, tagline=excluded.tagline, why=excluded.why, look=excluded.look, getting=excluded.getting, lat=excluded.lat, lon=excluded.lon, published=excluded.published;
insert into public.spots (id, city_id, name, type, genres, window_type, reason, tagline, why, look, getting, image_url, lat, lon, published) values (
  $vtg$parthenon$vtg$, $vtg$nashville$vtg$, $vtg$Parthenon$vtg$, $vtg$Architecture$vtg$, array[$vtg$Architecture$vtg$, $vtg$Landscape$vtg$]::text[], $vtg$golden$vtg$, $vtg$Full-scale Greek temple glowing at sunset$vtg$, $vtg$A full-scale Parthenon in the middle of a park$vtg$, $vtg$This is a full-scale replica of the Athens Parthenon, sitting right in the middle of Centennial Park, and it photographs like nothing else in Nashville. The Doric columns catch warm light beautifully as the sun drops, and the reflecting pond in front hands you a mirror composition on a calm evening. It's grand enough to fill a wide frame and detailed enough to reward you up close.$vtg$, array[$vtg$The west facade and columns backlit and glowing during the last hour of sun$vtg$, $vtg$A full reflection of the facade in the pond on a still evening$vtg$, $vtg$Tight detail on the fluted columns and pediment with raking side light$vtg$]::text[], $vtg$In Centennial Park on West End Ave, just west of downtown; free lot at the park with more street parking nearby.$vtg$, null, 36.149716, -86.813382, true)
  on conflict (id) do update set city_id=excluded.city_id, name=excluded.name, type=excluded.type, genres=excluded.genres, window_type=excluded.window_type, reason=excluded.reason, tagline=excluded.tagline, why=excluded.why, look=excluded.look, getting=excluded.getting, lat=excluded.lat, lon=excluded.lon, published=excluded.published;
insert into public.spots (id, city_id, name, type, genres, window_type, reason, tagline, why, look, getting, image_url, lat, lon, published) values (
  $vtg$belmont-mansion$vtg$, $vtg$nashville$vtg$, $vtg$Belmont Mansion$vtg$, $vtg$Architecture$vtg$, array[$vtg$Architecture$vtg$]::text[], $vtg$golden$vtg$, $vtg$Italianate villa glowing at golden hour$vtg$, $vtg$Antebellum grandeur on a Belmont hillside$vtg$, $vtg$Belmont Mansion is one of the South's grandest surviving 19th-century villas, and its Italianate details reward a slow, deliberate eye. The pink-cream facade, the ornate tower, and the cast-iron garden ornaments all catch warm light beautifully as the sun drops. It sits on the Belmont University campus, so you can work the exterior and grounds without fighting crowds.$vtg$, array[$vtg$The bell tower and arched windows backlit against a golden-hour sky$vtg$, $vtg$Cast-iron gazebo and statuary framed by the formal garden's lines$vtg$, $vtg$Detail shots of the ornate cornices and columns as low sun rakes the stucco$vtg$]::text[], $vtg$On the Belmont University campus off Belmont Blvd; street parking nearby, a short drive or bus ride from downtown.$vtg$, null, 36.135602, -86.794772, true)
  on conflict (id) do update set city_id=excluded.city_id, name=excluded.name, type=excluded.type, genres=excluded.genres, window_type=excluded.window_type, reason=excluded.reason, tagline=excluded.tagline, why=excluded.why, look=excluded.look, getting=excluded.getting, lat=excluded.lat, lon=excluded.lon, published=excluded.published;
insert into public.spots (id, city_id, name, type, genres, window_type, reason, tagline, why, look, getting, image_url, lat, lon, published) values (
  $vtg$capitol-hill$vtg$, $vtg$nashville$vtg$, $vtg$Capitol Hill$vtg$, $vtg$Architecture$vtg$, array[$vtg$Architecture$vtg$, $vtg$Landscape$vtg$]::text[], $vtg$golden$vtg$, $vtg$Greek Revival lines above the skyline$vtg$, $vtg$Tennessee's grandest building, crowning the city$vtg$, $vtg$The Tennessee State Capitol sits high on the hill, one of the oldest working capitol buildings in the country, and its Greek Revival columns catch late light beautifully. The grounds give you elevation and open sightlines back toward downtown, so you're shooting both the architecture and the city it looks over. It's a rare spot where formal symmetry and sweeping vista live side by side.$vtg$, array[$vtg$Warm side-light raking across the limestone columns at golden hour$vtg$, $vtg$The downtown skyline framed from the terrace as the sun drops west$vtg$, $vtg$Monuments and staircases on the grounds leading the eye up to the portico$vtg$]::text[], $vtg$Walking distance from downtown Nashville; street and garage parking nearby, easy on foot from Legislative Plaza.$vtg$, null, 36.165186, -86.784041, true)
