insert into public.spots (id, city_id, name, type, genres, window_type, reason, tagline, why, look, getting, image_url, lat, lon, published) values (
  $vtg$piedmont$vtg$, $vtg$atlanta$vtg$, $vtg$Piedmont Park$vtg$, $vtg$Nature$vtg$, array[$vtg$Nature$vtg$, $vtg$Landscape$vtg$]::text[], $vtg$golden$vtg$, $vtg$Open sky over Midtown$vtg$, $vtg$Meadow foreground · Midtown backdrop$vtg$, $vtg$Oak Hill's open lawn gives you an unobstructed western sky with the Midtown towers as a backdrop — golden grass in front, glowing glass behind.$vtg$, array[$vtg$Backlit grass on Oak Hill turns to gold near sunset.$vtg$, $vtg$Silhouettes of dog-walkers read clean against the sky.$vtg$, $vtg$The lake mirrors the skyline once the wind drops.$vtg$]::text[], $vtg$8 min drive · park at 12th & Piedmont · Oak Hill is a 6-min walk in.$vtg$, null, 33.785, -84.373, true)
  on conflict (id) do update set city_id=excluded.city_id, name=excluded.name, type=excluded.type, genres=excluded.genres, window_type=excluded.window_type, reason=excluded.reason, tagline=excluded.tagline, why=excluded.why, look=excluded.look, getting=excluded.getting, lat=excluded.lat, lon=excluded.lon, published=excluded.published;
insert into public.spots (id, city_id, name, type, genres, window_type, reason, tagline, why, look, getting, image_url, lat, lon, published) values (
  $vtg$ponce$vtg$, $vtg$atlanta$vtg$, $vtg$Ponce City Market Roof$vtg$, $vtg$Cityscape$vtg$, array[$vtg$Architecture$vtg$, $vtg$Landscape$vtg$]::text[], $vtg$blue$vtg$, $vtg$Rooftops and bridges light up$vtg$, $vtg$Elevated blue-hour panorama$vtg$, $vtg$From the roof the whole east side spreads out — the BeltLine, distant downtown, and a sky that deepens to cobalt as the city switches its lights on.$vtg$, array[$vtg$Shoot west toward downtown as the sky goes cobalt.$vtg$, $vtg$The BeltLine ribbon glows amber below.$vtg$, $vtg$Steady the camera on the rail for the long blue-hour frames.$vtg$]::text[], $vtg$11 min drive · rooftop entry via the elevator · check posted rooftop hours.$vtg$, null, 33.772, -84.365, true)
  on conflict (id) do update set city_id=excluded.city_id, name=excluded.name, type=excluded.type, genres=excluded.genres, window_type=excluded.window_type, reason=excluded.reason, tagline=excluded.tagline, why=excluded.why, look=excluded.look, getting=excluded.getting, lat=excluded.lat, lon=excluded.lon, published=excluded.published;
insert into public.spots (id, city_id, name, type, genres, window_type, reason, tagline, why, look, getting, image_url, lat, lon, published) values (
  $vtg$fairlie-poplar-historic-district$vtg$, $vtg$atlanta$vtg$, $vtg$Fairlie-Poplar Historic District$vtg$, $vtg$Architecture$vtg$, array[$vtg$Street$vtg$, $vtg$Architecture$vtg$]::text[], $vtg$blue$vtg$, $vtg$Terra-cotta facades and old streetlamps at dusk$vtg$, $vtg$Atlanta's oldest streets, still holding the light$vtg$, $vtg$This is where Atlanta's early-20th-century commercial architecture still stands shoulder to shoulder — narrow streets, ornate terra-cotta, and cast-iron detail packed into a walkable grid. The tight blocks throw dramatic shadow and reflection, and the mix of old brick against downtown's glass towers gives you layered frames everywhere you turn. It's quiet enough after work hours to actually work a composition without the crowd.$vtg$, array[$vtg$The Flatiron Building's narrow wedge from across Broad Street, catching the last warm light on its facade$vtg$, $vtg$Reflections and streetlamp glow along Broad Street pedestrian stretch once the blue hour sets in$vtg$, $vtg$Looking up into terra-cotta cornices and old signage against modern towers for a clean old-versus-new contrast$vtg$]::text[], $vtg$Downtown near Peachtree Center MARTA; walkable from most of the city core, with street parking easier in the evenings.$vtg$, null, 33.756495, -84.391038, true)
  on conflict (id) do update set city_id=excluded.city_id, name=excluded.name, type=excluded.type, genres=excluded.genres, window_type=excluded.window_type, reason=excluded.reason, tagline=excluded.tagline, why=excluded.why, look=excluded.look, getting=excluded.getting, lat=excluded.lat, lon=excluded.lon, published=excluded.published;
insert into public.spots (id, city_id, name, type, genres, window_type, reason, tagline, why, look, getting, image_url, lat, lon, published) values (
  $vtg$atl-nighthawks-at-the-diner$vtg$, $vtg$atlanta$vtg$, $vtg$ATL Nighthawks at the Diner$vtg$, $vtg$Street$vtg$, array[$vtg$Street$vtg$, $vtg$Portraits$vtg$]::text[], $vtg$blue$vtg$, $vtg$Diner glow and lone figures after dark$vtg$, $vtg$Warm counter light against the cold blue night$vtg$, $vtg$There's a Hopper-esque quiet to a late-night diner that few Atlanta scenes match. When the sky goes deep blue and the interior burns warm and amber through the glass, you get instant mood and separation. The regulars, the servers on their feet, the solitary coffee drinkers — they're honest portraits waiting to happen.$vtg$, array[$vtg$Shoot through the front glass at blue hour — warm interior against the cold sky$vtg$, $vtg$A lone figure hunched at the counter, framed by the row of stools$vtg$, $vtg$Steam off a coffee cup or grill, backlit by a window or hanging light$vtg$]::text[], $vtg$Easy to reach by car with street or lot parking nearby; check hours before a late-night visit.$vtg$, null, 33.759903, -84.391659, true)
  on conflict (id) do update set city_id=excluded.city_id, name=excluded.name, type=excluded.type, genres=excluded.genres, window_type=excluded.window_type, reason=excluded.reason, tagline=excluded.tagline, why=excluded.why, look=excluded.look, getting=excluded.getting, lat=excluded.lat, lon=excluded.lon, published=excluded.published;
insert into public.spots (id, city_id, name, type, genres, window_type, reason, tagline, why, look, getting, image_url, lat, lon, published) values (
  $vtg$look-at-them-look-at-us$vtg$, $vtg$atlanta$vtg$, $vtg$Look At Them Look At Us$vtg$, $vtg$Street art$vtg$, array[$vtg$Street$vtg$, $vtg$Portraits$vtg$]::text[], $vtg$flat$vtg$, $vtg$Bold mural portraits under even light$vtg$, $vtg$A wall that stares back on the Westside$vtg$, $vtg$This large-scale mural of oversized faces gives you something rare in street shooting: subjects that hold perfectly still and never break eye contact. The scale and direct gaze turn any passerby into part of the frame, and the flat, saturated color reads best without hard shadows cutting across it. It's a quick stop that rewards patience for the right person to walk through.$vtg$, array[$vtg$A real passerby small against the giant painted faces for scale$vtg$, $vtg$Tight crop on the eyes where the paint meets the wall's texture$vtg$, $vtg$Someone pausing mid-stride, caught between the mural's gaze and yours$vtg$]::text[], $vtg$On Atlanta's Westside near the BeltLine's western reaches; easiest by car or bike with street parking nearby.$vtg$, null, 33.756496, -84.391907, true)
  on conflict (id) do update set city_id=excluded.city_id, name=excluded.name, type=excluded.type, genres=excluded.genres, window_type=excluded.window_type, reason=excluded.reason, tagline=excluded.tagline, why=excluded.why, look=excluded.look, getting=excluded.getting, lat=excluded.lat, lon=excluded.lon, published=excluded.published;
insert into public.spots (id, city_id, name, type, genres, window_type, reason, tagline, why, look, getting, image_url, lat, lon, published) values (
  $vtg$state-farm-arena$vtg$, $vtg$atlanta$vtg$, $vtg$State Farm Arena$vtg$, $vtg$Street$vtg$, array[$vtg$Street$vtg$, $vtg$Architecture$vtg$]::text[], $vtg$blue$vtg$, $vtg$Crowd energy and glass under arena lights$vtg$, $vtg$Where the crowd and the concrete come alive at night$vtg$, $vtg$State Farm Arena turns into a stage of its own on game and concert nights, with rivers of fans, glowing signage, and modern glass and steel catching every light. The plaza around it gives you clean architectural lines by day and pure kinetic street energy after dark. Downtown's Centennial district hums right here, so you're never short of movement.$vtg$, array[$vtg$Fans streaming toward the entrance under the illuminated marquee at blue hour$vtg$, $vtg$Reflections of the skyline in the arena's glass facade just as lights kick on$vtg$, $vtg$Low-angle shot up the steel-and-glass exterior against the darkening sky$vtg$]::text[], $vtg$In downtown Atlanta near CNN Center; MARTA to GWCC/CNN Center or Dome station, with paid parking decks nearby.$vtg$, null, 33.757171, -84.396353, true)
  on conflict (id) do update set city_id=excluded.city_id, name=excluded.name, type=excluded.type, genres=excluded.genres, window_type=excluded.window_type, reason=excluded.reason, tagline=excluded.tagline, why=excluded.why, look=excluded.look, getting=excluded.getting, lat=excluded.lat, lon=excluded.lon, published=excluded.published;
insert into public.spots (id, city_id, name, type, genres, window_type, reason, tagline, why, look, getting, image_url, lat, lon, published) values (
  $vtg$underground-atlanta$vtg$, $vtg$atlanta$vtg$, $vtg$Underground Atlanta$vtg$, $vtg$Street$vtg$, array[$vtg$Street$vtg$, $vtg$Architecture$vtg$]::text[], $vtg$blue$vtg$, $vtg$Neon and brick corridors after dark$vtg$, $vtg$A city beneath the city, glowing after hours$vtg$, $vtg$Underground Atlanta is where the original city street level got buried and left behind, so you're shooting inside history — old storefronts, gaslight-era facades, and low brick arches lit by neon and string lights. It swings between gritty and vibrant depending on the night, which makes for honest street frames you won't get above ground. When events and vendors fill the space, the energy is loud and colorful.$vtg$, array[$vtg$Neon signage reflecting on wet brick along the lower promenade at dusk$vtg$, $vtg$The original 19th-century storefront facades framed under the arches$vtg$, $vtg$Vendors and passersby silhouetted against string-lit corridors$vtg$]::text[], $vtg$Right by Five Points MARTA station downtown; transit is easiest, with paid parking nearby.$vtg$, null, 33.752537, -84.390148, true)
  on conflict (id) do update set city_id=excluded.city_id, name=excluded.name, type=excluded.type, genres=excluded.genres, window_type=excluded.window_type, reason=excluded.reason, tagline=excluded.tagline, why=excluded.why, look=excluded.look, getting=excluded.getting, lat=excluded.lat, lon=excluded.lon, published=excluded.published;
insert into public.spots (id, city_id, name, type, genres, window_type, reason, tagline, why, look, getting, image_url, lat, lon, published) values (
  $vtg$podium-plaza$vtg$, $vtg$atlanta$vtg$, $vtg$Podium Plaza$vtg$, $vtg$Street$vtg$, array[$vtg$Street$vtg$, $vtg$Architecture$vtg$]::text[], $vtg$blue$vtg$, $vtg$Reflections and clean lines after dusk$vtg$, $vtg$Where hard lines meet moving crowds$vtg$, $vtg$Podium Plaza is that pocket of downtown Atlanta where modern glass towers frame a public open space, and the geometry does half the work for you. The mix of steel, stone, and reflective facades gives you strong lines by day and glowing reflections once the office lights come on. It's a spot that rewards patience — wait for a lone figure to cross and the whole frame clicks into place.$vtg$, array[$vtg$A single commuter crossing the plaza at blue hour, small against the tower glass$vtg$, $vtg$Reflections of lit windows pooling on polished stone after rain$vtg$, $vtg$Tight upward angles where two facades meet to make a clean diagonal$vtg$]::text[], $vtg$Central downtown — easiest by MARTA rail, with paid parking decks nearby.$vtg$, null, 33.759738, -84.393564, true)
  on conflict (id) do update set city_id=excluded.city_id, name=excluded.name, type=excluded.type, genres=excluded.genres, window_type=excluded.window_type, reason=excluded.reason, tagline=excluded.tagline, why=excluded.why, look=excluded.look, getting=excluded.getting, lat=excluded.lat, lon=excluded.lon, published=excluded.published;
insert into public.spots (id, city_id, name, type, genres, window_type, reason, tagline, why, look, getting, image_url, lat, lon, published) values (
  $vtg$olympic-rings$vtg$, $vtg$atlanta$vtg$, $vtg$Olympic Rings$vtg$, $vtg$Architecture$vtg$, array[$vtg$Architecture$vtg$]::text[], $vtg$blue$vtg$, $vtg$Interlocking rings glow after sunset$vtg$, $vtg$A '96 landmark that still lights up the night$vtg$, $vtg$Centennial Olympic Park's rings are a clean geometric subject that rewards patience. The interlocking shapes catch the fountain reflections and the surrounding downtown skyline, and once the city lights kick in they read boldly against the deep sky. It's one of the few spots in Atlanta where architecture, water, and history stack in a single frame.$vtg$, array[$vtg$The rings lit up at blue hour with the Skyview wheel or downtown towers stacked behind$vtg$, $vtg$Low-angle shot through one ring, using the arch as a natural frame for the fountain$vtg$, $vtg$Long-exposure of the Fountain of Rings jets nearby, kids running through the water on warm evenings$vtg$]::text[], $vtg$Centennial Olympic Park, walkable from downtown and the Peachtree Center MARTA station; nearby parking decks fill on event nights.$vtg$, null, 33.759732, -84.392262, true)
  on conflict (id) do update set city_id=excluded.city_id, name=excluded.name, type=excluded.type, genres=excluded.genres, window_type=excluded.window_type, reason=excluded.reason, tagline=excluded.tagline, why=excluded.why, look=excluded.look, getting=excluded.getting, lat=excluded.lat, lon=excluded.lon, published=excluded.published;
insert into public.spots (id, city_id, name, type, genres, window_type, reason, tagline, why, look, getting, image_url, lat, lon, published) values (
  $vtg$atlanta-botanical-garden$vtg$, $vtg$atlanta$vtg$, $vtg$Atlanta Botanical Garden$vtg$, $vtg$Nature$vtg$, array[$vtg$Architecture$vtg$, $vtg$Nature$vtg$, $vtg$Landscape$vtg$]::text[], $vtg$golden$vtg$, $vtg$Living sculptures and glass at golden hour$vtg$, $vtg$Where architecture and greenery grow into each other$vtg$, $vtg$The Botanical Garden layers glasshouse geometry against living color, so you get architectural lines and organic texture in the same frame. The Fuqua Orchid Center and the Canopy Walk give you elevated angles you won't find at ground level anywhere else in the city. Late light rakes across the manicured beds and turns the whole place warm and dimensional.$vtg$, array[$vtg$The Canopy Walk railing leading your eye out over the treetops in golden light$vtg$, $vtg$Backlit orchids and glass panels inside the Fuqua Conservatory$vtg$, $vtg$The Earth Goddess or seasonal topiary framed against a clean sky at dusk$vtg$]::text[], $vtg$On Piedmont Ave beside Piedmont Park; on-site parking deck, or transit and rideshare drop you at the entrance.$vtg$, null, 33.790604, -84.373828, true)
  on conflict (id) do update set city_id=excluded.city_id, name=excluded.name, type=excluded.type, genres=excluded.genres, window_type=excluded.window_type, reason=excluded.reason, tagline=excluded.tagline, why=excluded.why, look=excluded.look, getting=excluded.getting, lat=excluded.lat, lon=excluded.lon, published=excluded.published;
insert into public.spots (id, city_id, name, type, genres, window_type, reason, tagline, why, look, getting, image_url, lat, lon, published) values (
  $vtg$woodruff-park$vtg$, $vtg$atlanta$vtg$, $vtg$Woodruff Park$vtg$, $vtg$Nature$vtg$, array[$vtg$Nature$vtg$, $vtg$Street$vtg$, $vtg$Architecture$vtg$]::text[], $vtg$golden$vtg$, $vtg$Downtown greenery framed by towers at dusk$vtg$, $vtg$A pocket of green where downtown Atlanta slows down$vtg$, $vtg$Woodruff Park is that rare downtown square where trees, fountains, and glass towers all crowd into one frame. Late-day light rakes across the open lawn and catches the water feature just as office crowds and skaters give the place life. It's the spot to shoot nature and city in the same breath.$vtg$, array[$vtg$Golden-hour reflections off the surrounding glass towers pooling onto the lawn$vtg$, $vtg$The fountain and water wall backlit with skaters and passersby in silhouette$vtg$, $vtg$Tree canopy against the geometry of downtown high-rises from a low angle$vtg$]::text[], $vtg$In the heart of downtown at Peachtree and Auburn; easy walk from the Peachtree Center MARTA station.$vtg$, null, 33.755579, -84.38855, true)
  on conflict (id) do update set city_id=excluded.city_id, name=excluded.name, type=excluded.type, genres=excluded.genres, window_type=excluded.window_type, reason=excluded.reason, tagline=excluded.tagline, why=excluded.why, look=excluded.look, getting=excluded.getting, lat=excluded.lat, lon=excluded.lon, published=excluded.published;
insert into public.spots (id, city_id, name, type, genres, window_type, reason, tagline, why, look, getting, image_url, lat, lon, published) values (
  $vtg$liberty-plaza$vtg$, $vtg$atlanta$vtg$, $vtg$Liberty Plaza$vtg$, $vtg$Cityscape$vtg$, array[$vtg$Nature$vtg$, $vtg$Street$vtg$]::text[], $vtg$golden$vtg$, $vtg$Capitol backdrop and open-plaza light$vtg$, $vtg$Where the Gold Dome meets open sky$vtg$, $vtg$Liberty Plaza sits right across from the State Capitol, giving you a rare pocket of open sky and a clean sightline to that gold dome in the middle of downtown. The mix of hardscape, young trees, and government architecture makes it a quiet spot to shoot when the rallies and events aren't filling it. Late afternoon light rakes across the plaza and warms the dome beautifully.$vtg$, array[$vtg$The Gold Dome catching low golden-hour light framed between the plaza's trees$vtg$, $vtg$Long shadows stretching across the open pavement as people cross late in the day$vtg$, $vtg$Tight detail shots of leaves and branches against the Capitol's classical columns$vtg$]::text[], $vtg$Downtown near the State Capitol on Washington St; easy from MARTA's Georgia State station, with street and deck parking nearby.$vtg$, null, 33.748534, -84.387106, true)
  on conflict (id) do update set city_id=excluded.city_id, name=excluded.name, type=excluded.type, genres=excluded.genres, window_type=excluded.window_type, reason=excluded.reason, tagline=excluded.tagline, why=excluded.why, look=excluded.look, getting=excluded.getting, lat=excluded.lat, lon=excluded.lon, published=excluded.published;
insert into public.spots (id, city_id, name, type, genres, window_type, reason, tagline, why, look, getting, image_url, lat, lon, published) values (
  $vtg$georgia-aquarium$vtg$, $vtg$atlanta$vtg$, $vtg$Georgia Aquarium$vtg$, $vtg$Nature$vtg$, array[$vtg$Nature$vtg$, $vtg$Architecture$vtg$]::text[], $vtg$flat$vtg$, $vtg$Backlit ocean life in the dark tunnels$vtg$, $vtg$Whale sharks drift overhead in a wall of blue$vtg$, $vtg$The Ocean Voyager tunnel is one of the only places in the city where you can shoot whale sharks and manta rays gliding right over your head. The tanks glow a deep, even blue that does all the lighting work for you, so it's an all-weather spot — overcast or pouring outside, the light indoors never changes. It's slow, meditative shooting: you wait for the shape you want to swim into frame.$vtg$, array[$vtg$A whale shark's silhouette passing directly overhead in the acrylic tunnel$vtg$, $vtg$Backlit jellyfish drifting against pure black — pull exposure down for the glow$vtg$, $vtg$Kids' faces lit blue, pressed to the big Ocean Voyager viewing window$vtg$]::text[], $vtg$Downtown at Pemberton Place near Centennial Olympic Park; paid deck on site or take MARTA to Peachtree Center or GWCC/Omni.$vtg$, null, 33.763439, -84.394038, true)
  on conflict (id) do update set city_id=excluded.city_id, name=excluded.name, type=excluded.type, genres=excluded.genres, window_type=excluded.window_type, reason=excluded.reason, tagline=excluded.tagline, why=excluded.why, look=excluded.look, getting=excluded.getting, lat=excluded.lat, lon=excluded.lon, published=excluded.published;

